package com.refrigeracionpro.app;

import android.app.*;
import android.os.Bundle;
import android.content.*;
import android.database.Cursor;
import android.database.sqlite.*;
import android.graphics.Typeface;
import android.graphics.Color;
import android.view.*;
import android.widget.*;
import java.text.SimpleDateFormat;
import java.util.*;

public class MainActivity extends Activity {
    final int BG=Color.rgb(8,13,22), PANEL=Color.rgb(17,26,41), BLUE=Color.rgb(38,168,255), WHITE=Color.rgb(239,245,255), MUTED=Color.rgb(151,169,193), GREEN=Color.rgb(59,209,146);
    LinearLayout root, body; DB db; String section="Inicio";
    public void onCreate(Bundle b){super.onCreate(b); getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);db=new DB(this); showHome();}
    TextView text(String s,int size,int color,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);if(bold)t.setTypeface(null,Typeface.BOLD);t.setPadding(0,4,0,8);return t;}
    void base(String title,String subtitle){root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(BG);root.setPadding(18,16,18,10);setContentView(root); TextView brand=text("❄  REFRIGERACIÓN PRO",12,BLUE,true);root.addView(brand);root.addView(text(title,27,WHITE,true));root.addView(text(subtitle,13,MUTED,false)); ScrollView scroll=new ScrollView(this);body=new LinearLayout(this);body.setOrientation(1);scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1)); LinearLayout nav=new LinearLayout(this);nav.setPadding(0,8,0,0);String[] names={"Inicio","Diagnóstico","Clientes","Cotizar","Historial"};for(String n:names){Button b=navButton(n);nav.addView(b,new LinearLayout.LayoutParams(0,48,1));}root.addView(nav); }
    Button navButton(String s){Button b=new Button(this);b.setText(s.equals("Diagnóstico")?"Diag.":s);b.setTextSize(10);b.setTextColor(s.equals(section)?BLUE:WHITE);b.setBackgroundColor(BG);b.setPadding(0,0,0,0);b.setOnClickListener(v->{if(s.equals("Inicio"))showHome();else if(s.equals("Diagnóstico"))showDiagnosis();else if(s.equals("Clientes"))showClients();else if(s.equals("Cotizar"))showQuote();else showHistory();});return b;}
    void card(String title,String desc,Runnable action){LinearLayout c=new LinearLayout(this);c.setOrientation(1);c.setPadding(16,12,16,10);c.setBackgroundColor(PANEL);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,7,0,7);body.addView(c,lp);c.addView(text(title,17,WHITE,true));c.addView(text(desc,13,MUTED,false));if(action!=null){Button b=new Button(this);b.setText("Abrir  →");b.setTextColor(BLUE);b.setBackgroundColor(PANEL);b.setOnClickListener(v->action.run());c.addView(b);} }
    EditText field(String hint){EditText e=new EditText(this);e.setSingleLine(false);e.setTextColor(WHITE);e.setHintTextColor(MUTED);e.setHint(hint);e.setTextSize(15);e.setPadding(12,8,12,8);e.setBackgroundTintList(android.content.res.ColorStateList.valueOf(BLUE));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,4,0,7);body.addView(e,p);return e;}
    void label(String s){body.addView(text(s,13,MUTED,true));}
    void button(String s,Runnable r){Button b=new Button(this);b.setText(s);b.setTextColor(Color.WHITE);b.setAllCaps(false);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(BLUE));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,10,0,12);body.addView(b,p);b.setOnClickListener(v->r.run());}
    String val(EditText e){return e.getText().toString().trim();}
    void showHome(){section="Inicio";base("Tu taller, bajo control","Herramientas para servicio técnico · Funciona sin Internet");card("DIAGNÓSTICO TÉCNICO","Síntomas, mediciones, refrigerante y posibles causas",()->showDiagnosis());card("CLIENTES Y EQUIPOS","Guarda contactos y datos de los equipos",()->showClients());card("COTIZACIONES","Calcula material, mano de obra, gastos y utilidad",()->showQuote());card("HISTORIAL DE SERVICIOS","Consulta los registros guardados en este teléfono",()->showHistory());Cursor c=db.getReadableDatabase().rawQuery("SELECT COUNT(*), COALESCE(SUM(profit),0) FROM records WHERE kind='quote'",null);c.moveToFirst();card("RESUMEN","Cotizaciones guardadas: "+c.getInt(0)+"\nUtilidad registrada: $"+String.format(Locale.getDefault(),"%.2f",c.getDouble(1)),null);c.close();card("IMPORTANTE","Las sugerencias de diagnóstico son una guía. Confirma las mediciones y la seguridad del equipo antes de intervenir.",null);}
    void showDiagnosis(){section="Diagnóstico";base("Diagnóstico técnico","Registra el caso y las lecturas del equipo");label("Cliente / referencia");EditText client=field("Nombre o referencia del cliente");label("Equipo");EditText equip=field("Marca, modelo y tipo de refrigerador");label("Refrigerante");EditText gas=field("Ej. R600a, R134a, R290");label("Síntomas");EditText symptom=field("No enfría, hielo, fuga, ruido…");label("Mediciones");EditText readings=field("Presiones, amperaje, temperaturas, gramos, resistencias…");label("Diagnóstico / siguientes comprobaciones");EditText diagnosis=field("Posibles causas y pruebas por realizar");button("Guardar diagnóstico",()->{if(val(symptom).isEmpty()){toast("Escribe al menos los síntomas");return;}db.add("diagnosis",val(client),val(equip),"Síntomas: "+val(symptom)+"\nRefrigerante: "+val(gas)+"\nMediciones: "+val(readings)+"\nDiagnóstico: "+val(diagnosis),0,0,0);toast("Diagnóstico guardado en este teléfono");showHistory();});}
    void showClients(){section="Clientes";base("Clientes y equipos","Directorio local, sin sincronización en la nube");label("Nombre");EditText name=field("Nombre del cliente");label("Teléfono");EditText phone=field("Teléfono (opcional)");label("Dirección / zona");EditText address=field("Dirección o colonia (opcional)");label("Equipo");EditText equipment=field("Marca, modelo y tipo de equipo");label("Notas");EditText notes=field("Detalles útiles del servicio");button("Guardar cliente",()->{if(val(name).isEmpty()){toast("Escribe el nombre del cliente");return;}db.add("client",val(name),val(equipment),"Teléfono: "+val(phone)+"\nZona: "+val(address)+"\nNotas: "+val(notes),0,0,0);toast("Cliente guardado");showHistory();});card("Privacidad","Los datos se guardan localmente en la aplicación. Haz respaldos por tu cuenta si necesitas conservarlos al cambiar de teléfono.",null);}
    void showQuote(){section="Cotizar";base("Cotización y utilidad","Importes en pesos mexicanos (MXN)");label("Cliente / trabajo");EditText customer=field("Cliente y descripción del servicio");label("Materiales y refacciones ($)");EditText materials=field("0.00");label("Mano de obra cobrada ($)");EditText labor=field("0.00");label("Otros gastos ($)");EditText expenses=field("Gasolina, ayudante, consumibles…");label("Total cobrado ($)");EditText charge=field("0.00");TextView result=text("La utilidad estimada aparecerá aquí.",16,GREEN,true);body.addView(result);button("Calcular y guardar",()->{try{double m=num(val(materials)),l=num(val(labor)),e=num(val(expenses)),t=num(val(charge));double cost=m+e,profit=t-cost;result.setText("Costo registrado: $"+money(cost)+"\nTotal cobrado: $"+money(t)+"\nUTILIDAD ESTIMADA: $"+money(profit));db.add("quote",val(customer),"Cotización", "Materiales: $"+money(m)+"\nMano de obra: $"+money(l)+"\nOtros gastos: $"+money(e)+"\nTotal cobrado: $"+money(t),t,profit,cost);toast("Cotización guardada");}catch(Exception ex){toast("Revisa los importes: usa números, por ejemplo 450.00");}});card("Cómo se calcula","Costo registrado = materiales + otros gastos. Utilidad estimada = total cobrado − costo registrado. La mano de obra cobrada forma parte del total que cobras al cliente; no se suma dos veces.",null);}
    double num(String s){return s.isEmpty()?0:Double.parseDouble(s.replace(",","."));}String money(double n){return String.format(Locale.getDefault(),"%.2f",n);}void showHistory(){section="Historial";base("Historial local","Registros guardados en este dispositivo");Cursor c=db.getReadableDatabase().rawQuery("SELECT id,kind,name,details,total,profit,created FROM records ORDER BY id DESC",null);if(c.getCount()==0)card("Todavía no hay registros","Guarda un diagnóstico, cliente o cotización para verlo aquí.",null);while(c.moveToNext()){final int id=c.getInt(0);String kind=c.getString(1),name=c.getString(2),details=c.getString(3);String title=(kind.equals("quote")?"💰 COTIZACIÓN":kind.equals("client")?"👤 CLIENTE":"🔧 DIAGNÓSTICO")+" · "+name;String extra=details+"\nFecha: "+c.getString(6);if(kind.equals("quote"))extra+="\nTotal: $"+money(c.getDouble(4))+" · Utilidad: $"+money(c.getDouble(5));card(title,extra,()->new AlertDialog.Builder(this).setTitle("Eliminar registro").setMessage("¿Quieres eliminar este registro de forma permanente?").setNegativeButton("Cancelar",null).setPositiveButton("Eliminar",(d,w)->{db.getWritableDatabase().delete("records","id=?",new String[]{String.valueOf(id)});showHistory();}).show());}c.close();button("Borrar todos los registros…",()->new AlertDialog.Builder(this).setTitle("Borrar historial").setMessage("Esto eliminará todos los clientes, diagnósticos y cotizaciones guardados en esta aplicación.").setNegativeButton("Cancelar",null).setPositiveButton("Borrar todo",(d,w)->{db.getWritableDatabase().delete("records",null,null);showHistory();}).show());}
    void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
    class DB extends SQLiteOpenHelper {DB(Context c){super(c,"refrigeracion_pro.db",null,1);}public void onCreate(SQLiteDatabase d){d.execSQL("CREATE TABLE records(id INTEGER PRIMARY KEY AUTOINCREMENT,kind TEXT,name TEXT,equipment TEXT,details TEXT,total REAL,profit REAL,cost REAL,created TEXT)");}public void onUpgrade(SQLiteDatabase d,int o,int n){}void add(String kind,String name,String equipment,String details,double total,double profit,double cost){android.content.ContentValues v=new android.content.ContentValues();v.put("kind",kind);v.put("name",name.isEmpty()?equipment:name);v.put("equipment",equipment);v.put("details",details);v.put("total",total);v.put("profit",profit);v.put("cost",cost);v.put("created",new SimpleDateFormat("dd/MM/yyyy HH:mm",Locale.getDefault()).format(new Date()));getWritableDatabase().insert("records",null,v);}}
}
